#. Consider the question #2 with customer name, meter ID, and phone number as additional 
# information. Now, use dictionary and display the bill for 10 (user-defined) customers. 
# Note that the meter ID is randomly generated by system, but each customer has unique
#  meter ID (no same ID for two customers).

import random

list = []

#run loop for 1st 10 users

for i in range(10):

    user_bill ={
    "name": "",
    "meter_ID":"",
    "units": 0,
    "total_bill": 0,
    "phone_number": ""
}

    user_bill["name"] = input("Enter your name:")
    user_bill["units"] = int(input("Enter the number of units you consumed: ")) 
    user_bill["phone_number"] = input("Enter your phone number: ") 

    #lets generate random meter ID for users

    user_bill["meter_ID"] = random.randint(100000,999999)

    #set billing rule accordingly

    if user_bill["units"] >=0 and user_bill["units"] <=50:
    
        user_bill["total_bill"] = user_bill["units"] * 2
       # print("your total bill is: ", user_bill["total_bill"], "Rs")
    
    elif user_bill["units"] >=51 and user_bill["units"] <=100:
    
        user_bill["total_bill"] = 100+ ((user_bill["units"]-50)*3)
       # print("your total bill is: ", user_bill["total_bill"], "Rs")
    
    elif user_bill["units"] >=101 and user_bill["units"] <=150:
    
        user_bill["total_bill"] = 250+ ((user_bill["units"]-100)*5)
        # print("your total bill is: ", user_bill["total_bill"], "Rs")    
    
    elif user_bill["units"] >=151 and user_bill["units"] <=200:
    
        user_bill["total_bill"] = 500+ ((user_bill["units"]-150)*6)
        # print("your total bill is: ", user_bill["total_bill"] , "Rs")
            
    elif user_bill["units"] >=201:
    
        user_bill["total_bill"] = 800+ ((user_bill["units"]-200)*8)
        # print("your total bill is: ", user_bill["total_bill"] , "Rs")    
    
    list.append(user_bill)


for bill in list:
    print(bill)